package com.tarapickle.identity.api; import com.tarapickle.identity.api.IdentityDtos.*; import com.tarapickle.identity.application.AccountService; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/account") @RequiredArgsConstructor @Tag(name="Account") @SecurityRequirement(name="bearerAuth") public class AccountController {private final AccountService service; @GetMapping("/me") @Operation(operationId="getCurrentAccount",summary="Get current account") public AccountResponse me(@AuthenticationPrincipal Jwt jwt){return service.me(AuthenticationController.uid(jwt));} @PatchMapping("/me") @Operation(operationId="updateCurrentAccount",summary="Update current account") public AccountResponse update(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody UpdateAccountRequest request){return service.update(AuthenticationController.uid(jwt),request);}}
